    for dirpath, _dirnames, filenames in os.walk(root):
        for name in filenames:
            full = os.path.join(dirpath, name)
            entries[os.path.relpath(full, root)] = full
    return entries


def stat_signature(path: str) -> Optional[Tuple[int, int]]:
    """返回用于"内容是否变化"判定的签名。

    签名由大小与修改时间共同构成；读取失败时返回 ``None``。
    """
    try:
        info = os.stat(path)
    except OSError:
        return None
    return (info.st_size, info.st_mtime_ns)


def content_hash(path: str) -> Optional[str]:
    """计算文件内容的 SHA-256 哈希值。

    读取失败时返回 ``None``。
    """
    try:
        hasher = hashlib.sha256()
        with open(path, "rb") as f:
            while chunk := f.read(1024 * 1024):
                hasher.update(chunk)
        return hasher.hexdigest()
    except OSError:
        return None


def is_readonly(path: str) -> bool:
    """路径是否带有只读属性。"""
    try:
        info = os.stat(path)
    except OSError:
        return False
    return not bool(info.st_mode & stat.S_IWRITE)


def clear_readonly(path: str) -> None:
    """清除路径的只读属性（如果有的话）。"""
    try:
        if is_readonly(path):
            os.chmod(path, stat.S_IWRITE | stat.S_IREAD)
    except OSError:
        pass


def remove_file(path: str) -> None:
    """删除单个文件。"""
    clear_readonly(path)
    os.remove(path)


def _clear_readonly_recursive(path: str) -> None:
    """递归清除目录树中所有条目的只读属性。"""
    try:
        if os.path.isfile(path):
            clear_readonly(path)
        elif os.path.isdir(path):
            clear_readonly(path)
            for entry in os.listdir(path):
                _clear_readonly_recursive(os.path.join(path, entry))
    except OSError:
        pass


def remove_tree(path: str) -> None:
    """递归删除一棵目录树。"""
    _clear_readonly_recursive(path)
    shutil.rmtree(path)


def _clear_conflicting_path(path: str) -> None:
    """如果路径存在且类型与预期冲突，清除它。

    调用方准备在此路径创建文件时使用。
    """
    try:
        if os.path.isdir(path):
            remove_tree(path)
        elif os.path.exists(path):
            remove_file(path)
    except OSError:
        pass


def copy_file(source: str, target: str) -> None:
    """把 ``source`` 的内容写到 ``target``，必要时创建父目录。"""
    # 清除目标路径上可能存在的目录
    _clear_conflicting_path(target)

    # 确保父目录存在，如果父路径被文件占用也要清理
    parent = os.path.dirname(target)
    if parent:
        # 清除父路径链上的所有文件冲突
        parts = []
        current = parent
        while current:
            parts.append(current)
            current = os.path.dirname(current)
        parts.reverse()

        for part in parts:
            if os.path.isfile(part):
                remove_file(part)
            if not os.path.exists(part):
                break

        os.makedirs(parent, exist_ok=True)

    # 复制内容
    with open(source, "rb") as src_handle, open(target, "wb") as dst_handle:
        shutil.copyfileobj(src_handle, dst_handle, length=1024 * 1024)

    # 保留源文件的修改时间
    try:
        src_stat = os.stat(source)
        os.utime(target, (src_stat.st_atime, src_stat.st_mtime))
    except OSError:
        pass


def prune_empty_dirs(root: str) -> None:
    """自底向上删除目标树中的空目录（不含 ``root`` 自身）。"""
    root = os.path.abspath(root)
    for dirpath, _dirnames, _filenames in os.walk(root, topdown=False):
        if os.path.abspath(dirpath) == root:
            continue
        try:
            if not os.listdir(dirpath):
                clear_readonly(dirpath)
                os.rmdir(dirpath)
        except OSError:
            pass
